          <span className="font-['Inter:Regular',sans-serif] font-normal leading-[26px] text-[16px]">{` GRN is always linked to a PO — supervisors select the PO and the system pre-fills expected items and quantities. Received quantity fields default to the expected quantity; supervisor adjusts downward for shortfalls. Any discrepancy triggers a formal discrepancy note, routed automatically to the procurement officer. Batch numbers and expiry dates are captured during receipt — seeding the compliance and inventory modules.`}</span>
